}

$AgyExe = Find-Antigravity
$AgyCurrentVersion = if ($AgyExe) { Get-VersionFromText ((& $AgyExe --version 2>$null) -join "`n") } else { '' }
$AgyLatestVersion = ''
$AgyNeedsUpdate = $true
